import styled from 'styled-components'
import { cores } from '../../styles'
import { Props } from '.'

export const TagContainer = styled.div<Props>`
  background-color: ${cores.verde};
  color: ${cores.rosa};
  height: auto;
  font-size: 10px;
  font-weight: bold;
  padding: ${(props) => (props.size === 'big' ? '4px 6px' : '4px 6px')};
  border-radius: 8px;
  display: inline-block;
`
